/* =========================================================
   Puff · 长夜＆机械之心 × 樱花晨光玻璃
   ========================================================= */

/* 1. 全局变量与方角设定 */
.off-app {
  --off-list-radius: 0px;
  --off-list-ava-size: 52px;
  --off-pink: #efb8cb;
  --off-glass-border: rgba(255, 255, 255, 0.82);
  --off-glass-shadow: 0 8px 30px rgba(125, 88, 103, 0.055), inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

/* 强制所有元素变方角 */
.off-app .off-list,
.off-app .off-list-ava,
.off-app.off-app-session .off-passage-sheet,
.off-app .off-compose-bar,
.off-inbox-filter,
.off-inbox-filter button,
.off-app .off-thinking-chip {
  border-radius: 0 !important;
}

/* 2. 核心注入：全局背景图 */
.off-app,
.off-app .off-stage,
.off-app.off-app-session .off-stage,
.off-app.off-app-session .off-stage.has-bg {
  background-color: transparent !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
}
.off-app .off-stage, 
.off-app .off-prose-scroll {
  background-color: transparent !important;
}

/* 3. 筛选器 */
.off-inbox-filter {
  background: rgba(255, 255, 255, 0.65) !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
  backdrop-filter: blur(20px) saturate(125%) !important;
}
.off-inbox-filter button { color: #a69a9f !important; background: transparent !important; }
.off-inbox-filter button.on {
  color: #fff !important;
  background: linear-gradient(135deg, #f5c9d9, #efb5ca) !important;
  box-shadow: 0 4px 12px rgba(225, 164, 186, 0.18) !important;
}

/* 4. 共处入口列表 */
.off-app:not(.off-app-session) .off-stage-head h1,
.off-app:not(.off-app-session) .off-stage-head h2,
.off-app:not(.off-app-session) .off-stage-head span,
.off-app:not(.off-app-session) .off-title,
.off-app .off-title {
  color: #000000 !important; 
  -webkit-text-fill-color: #000000 !important; 
  text-shadow: 0 2px 6px rgba(255, 255, 255, 0.95) !important; 
}
.off-app:not(.off-app-session) .off-list {
  background: rgba(255, 247, 250, 0.7) !important; 
  border: 1px solid var(--off-glass-border) !important;
  backdrop-filter: blur(28px) saturate(125%) !important;
  box-shadow: var(--off-glass-shadow) !important;
  overflow: hidden !important;
}
.off-list-btn { 
  border-bottom: 1px solid rgba(255, 255, 255, 0.6) !important; 
  background: transparent !important; 
}
.off-list-body strong { color: #4a4347 !important; font-weight: 600 !important; }
.off-list-body span { color: #91878b !important; }

/* 5. 顶栏 + 心电图 + 爱心 */
.off-app.off-app-session .off-stage-head {
  background: rgba(255, 255, 255, 0.55) !important; 
  backdrop-filter: blur(24px) saturate(125%) !important;
  border-bottom: none !important;
  position: relative !important;
  overflow: visible !important;
  z-index: 10 !important;
}
.off-app.off-app-session .off-stage-head::after {
  content: "" !important; position: absolute !important; bottom: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow 3s linear infinite !important; z-index: 99 !important;
}
.off-app.off-app-session .off-stage-head::before {
  content: '♥' !important; position: absolute !important; bottom: -23px !important; left: 10% !important; font-size: 16px !important;
  color: #ec7ca0 !important; text-shadow: 0 0 6px rgba(236, 124, 160, 0.9) !important; 
  z-index: 999 !important; pointer-events: none !important;
  animation: heart-walk 4s ease-in-out infinite alternate !important;
}

/* 6. 消息卡片 */
.off-app.off-app-session {
  --off-card-user: linear-gradient(135deg, rgba(255, 231, 239, 0.85), rgba(255, 247, 250, 0.85));
  --off-card-peer: rgba(255, 255, 255, 0.75);
  --off-card-border: rgba(255, 255, 255, 0.92);
  --off-card-shadow: 0 8px 30px rgba(110, 75, 90, 0.055), inset 0 1px 0 rgba(255, 255, 255, 0.9);
}
.off-app.off-app-session .off-passage-sheet {
  background: var(--off-card-peer) !important;
  border: 1px solid var(--off-card-border) !important;
  box-shadow: var(--off-card-shadow) !important;
  backdrop-filter: blur(24px) saturate(125%) !important;
}
.off-app.off-app-session .off-passage.is-me .off-passage-sheet {
  background: var(--off-card-user) !important;
  border-color: rgba(242, 191, 208, 0.5) !important;
}
.off-app.off-app-session .off-prose-para,
.off-app.off-app-session .off-prose-narr,
.off-app.off-app-session .off-prose-plain {
  color: #4a4347 !important; line-height: 1.85 !important; font-size: 14.5px !important;
}

/* =========================================================
   👇 核心：日间对话与引用（字多大框多大 + 行内果冻玻璃）
   ========================================================= */
.off-app.off-app-session .off-prose-dial,
.off-app.off-app-session [class*="dial"],
.off-app .off-compose-quote,
.off-app .off-passage-quote,
.off-app [class*="quote"] {
  display: inline !important; /* 关键：行内模式，字多大框多大 */
  box-decoration-break: clone !important; /* 关键：换行时每一行都有独立的高光圆角 */
  -webkit-box-decoration-break: clone !important;

  /* 玻璃质感设定 */
  background: linear-gradient(135deg, rgba(255, 242, 246, 0.75), rgba(255, 255, 255, 0.6)) !important;
  border: 1px solid rgba(255, 255, 255, 0.95) !important; /* 细白高光边框 */
  border-left: none !important; /* 绝不要侧边栏 */
  border-radius: 6px !important; /* 像小气泡一样的微圆角 */
  padding: 2px 8px !important; /* 上下贴身，左右留一点果冻边 */
  margin: 0 2px !important; /* 行与行之间留一点点缝 */

  box-shadow: inset 0 1px 2px rgba(255, 255, 255, 1), 0 2px 8px rgba(236, 124, 160, 0.15) !important;
  backdrop-filter: blur(10px) !important; /* 毛玻璃让背后的星空变柔和 */
  -webkit-backdrop-filter: blur(10px) !important;
}
.off-app.off-app-session .off-prose-dial *,
.off-app.off-app-session [class*="dial"] *,
.off-app .off-compose-quote *,
.off-app .off-passage-quote *,
.off-app [class*="quote"] * {
  color: #3a2330 !important; 
  font-family: "Noto Serif SC", "Songti SC", serif !important; 
}

/* =========================================================
   👇 长按悬浮菜单（日间樱花玻璃）
   ========================================================= */
.off-app [class*="menu"], .off-app [class*="popover"], .off-app [class*="popup"], .off-app [class*="dialog"], .off-app [class*="action"] {
  background: rgba(255, 248, 250, 0.95) !important;
  backdrop-filter: blur(24px) !important;
  border: 1.5px solid rgba(255, 255, 255, 1) !important;
  border-radius: 16px !important;
  box-shadow: 0 12px 36px rgba(236, 124, 160, 0.25) !important;
}
.off-app [class*="menu"] *, .off-app [class*="popover"] *, .off-app [class*="popup"] * { background: transparent !important; }
.off-app [class*="menu"] [class*="preview"], .off-app [class*="menu"] [class*="text"], .off-app [class*="menu"] [class*="content"] {
  color: #7a5b6c !important; font-family: "Songti SC", serif !important; border-bottom: 1px dashed rgba(236, 124, 160, 0.4) !important;
}
.off-app [class*="menu"] button, .off-app [class*="menu"] span, .off-app [class*="menu"] svg { color: #4a3340 !important; fill: #4a3340 !important; }
.off-app [class*="delete"] *, .off-app [class*="danger"] * { color: #ec7ca0 !important; fill: #ec7ca0 !important; }

/* 7. 底栏 + 发送框背后 */
.off-app.off-app-session .off-stage-dock {
  background: rgba(255, 250, 252, 0.65) !important; 
  backdrop-filter: blur(24px) saturate(130%) !important;
  border-top: none !important; position: relative !important; overflow: visible !important; z-index: 10 !important;
  padding-top: 20px !important; padding-bottom: 20px !important; 
}
.off-app.off-app-session .off-stage-dock::before {
  content: "" !important; position: absolute !important; top: -16px !important; left: 0 !important; right: 0 !important; height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; background-repeat: repeat-x !important;
  animation: ecg-flow-reverse 3s linear infinite !important; z-index: 99 !important;
}

/* 8. 输入框 */
.off-app .off-compose-bar {
  background: rgba(255, 255, 255, 0.75) !important;
  border: 1px solid rgba(255, 255, 255, 0.95) !important;
  backdrop-filter: blur(24px) saturate(125%) !important;
  box-shadow: 0 5px 20px rgba(110, 75, 90, 0.055) !important;
}
.off-compose-send {
  background: linear-gradient(135deg, #f4c7d8, #edb4ca) !important;
  color: #fff !important;
}

/* 9. 日间头像 */
.off-app .off-list-ava,
.off-app .chat-ava-list {
  border-radius: 14px !important; border: 1.5px solid rgba(255, 255, 255, 0.95) !important; 
  background: linear-gradient(135deg, #fff5f8, #fbcbdf) !important; padding: 2px !important;
  box-shadow: inset 0 0 6px rgba(255, 255, 255, 1), 0 0 12px rgba(236, 124, 160, 0.4) !important; 
  animation: jelly-glow 3s ease-in-out infinite alternate !important; 
}
.off-app .off-list-ava img,
.off-app .chat-ava-list img {
  border-radius: 11px !important; object-fit: cover !important;
}

/* 动画 */
@keyframes ecg-flow { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes ecg-flow-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }
@keyframes heart-walk {
  0% { left: 4%; transform: translateY(0) scale(1); } 30% { transform: translateY(-4px) scale(1.15); } 
  60% { transform: translateY(0) scale(1); } 80% { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}
@keyframes jelly-glow {
  0% { box-shadow: inset 0 0 6px rgba(255, 255, 255, 1), 0 0 4px rgba(236, 124, 160, 0.2); }
  100% { box-shadow: inset 0 0 8px rgba(255, 255, 255, 1), 0 0 16px rgba(236, 124, 160, 0.6); }
}
